namespace OpenSkyHRM.Application.Common;

public static class EmployeeEmailHelper
{
    public const string PlaceholderDomain = "@employee.noemail.opensky.hrm";

    /// <summary>Generated by older bulk imports when the row had no work email.</summary>
    public const string LegacyImportPlaceholderDomain = "@import.openskyhrm.local";

    public static bool IsPlaceholder(string? email) =>
        !string.IsNullOrWhiteSpace(email)
        && (email.Trim().Contains(PlaceholderDomain, StringComparison.OrdinalIgnoreCase)
            || email.Trim().EndsWith(LegacyImportPlaceholderDomain, StringComparison.OrdinalIgnoreCase));

    public static string? ToDisplayEmail(string? email)
    {
        if (string.IsNullOrWhiteSpace(email) || IsPlaceholder(email)) return null;
        return email.Trim();
    }

    public static string? NormalizeForSave(string? email)
    {
        var trimmed = email?.Trim();
        if (string.IsNullOrEmpty(trimmed) || IsPlaceholder(trimmed)) return null;
        return trimmed;
    }

    /// <summary>
    /// Work email for new employees. When the user leaves email blank, stores a unique
    /// internal placeholder so older databases where Email is NOT NULL still accept the row.
    /// UI hides placeholders via <see cref="ToDisplayEmail"/>.
    /// </summary>
    public static string ResolveForCreate(string employeeCode, string? email)
    {
        var normalized = NormalizeForSave(email);
        if (!string.IsNullOrEmpty(normalized)) return normalized;

        var code = employeeCode.Trim();
        if (string.IsNullOrEmpty(code))
            throw new InvalidOperationException("Employee code is required.");

        return $"{code.ToLowerInvariant()}{PlaceholderDomain}";
    }
}
